INSERT INTO gis_data_sources (name,provider_type,authority_name,jurisdiction_code,source_url,service_type,license_text,provenance_notes,refresh_policy,reliability_score,status) SELECT 'Ekiti State Geospatial Data Center','Government GIS','Ekiti State Government / EK-SGDC','NG-EK','https://ekitigeospatial.com/','State geospatial portal','Use subject to source authority/licence terms','Official state geospatial institution; source for land administration and geospatial records.','Manual',95,'Active' WHERE NOT EXISTS (SELECT 1 FROM gis_data_sources WHERE name='Ekiti State Geospatial Data Center');
INSERT INTO gis_data_sources (name,provider_type,authority_name,jurisdiction_code,source_url,service_type,license_text,provenance_notes,refresh_policy,reliability_score,status) SELECT 'Ekiti State Government Land Services','Government land administration','Ekiti State Bureau of Land Services','NG-EK','https://www.ekitistate.gov.ng/','Land administration / document source','Use subject to government terms','Official source for land-service procedures, title documentation and land administration context.','Manual',95,'Active' WHERE NOT EXISTS (SELECT 1 FROM gis_data_sources WHERE name='Ekiti State Government Land Services');
INSERT INTO gis_data_sources (name,provider_type,authority_name,jurisdiction_code,source_url,service_type,license_text,provenance_notes,refresh_policy,reliability_score,status) SELECT 'OpenStreetMap Nigeria','Open geospatial community','OpenStreetMap Foundation / contributors','NG','https://www.openstreetmap.org/','Vector map / OSM','ODbL; verify attribution and downstream licence obligations','Contextual infrastructure and place data; not authoritative cadastral title evidence.','Weekly',85,'Active' WHERE NOT EXISTS (SELECT 1 FROM gis_data_sources WHERE name='OpenStreetMap Nigeria');
INSERT INTO gis_data_sources (name,provider_type,authority_name,jurisdiction_code,source_url,service_type,license_text,provenance_notes,refresh_policy,reliability_score,status) SELECT 'Ekiti State Environmental and Planning Framework','Government regulatory context','Ekiti State Government','NG-EK','https://www.ekitistate.gov.ng/laws-and-regulations','Regulatory / planning source','Use subject to government terms','Used to identify planning and environmental regulatory context; geometry must be obtained from an authoritative GIS layer before spatial adjudication.','Manual',90,'Active' WHERE NOT EXISTS (SELECT 1 FROM gis_data_sources WHERE name='Ekiti State Environmental and Planning Framework');
INSERT INTO gis_layers (source_id,layer_code,layer_name,layer_key,name,description,geometry_type,crs,format,authority_name,jurisdiction_code,confidence_score,verification_status,visibility,status) SELECT id,'EK-AUTH-LAND','Ekiti Authoritative Land Layer','ekiti_authoritative_land','Ekiti Authoritative Land Layer','Placeholder for officially supplied/certified land or cadastral features; no geometry is fabricated by ÒsánVault.','Polygon','EPSG:4326','GeoJSON','Ekiti State Geospatial Data Center','NG-EK',98,'Pending Source','Restricted','Active' FROM gis_data_sources WHERE name='Ekiti State Geospatial Data Center' AND NOT EXISTS (SELECT 1 FROM gis_layers WHERE layer_key='ekiti_authoritative_land');
INSERT INTO gis_layers (source_id,layer_code,layer_name,layer_key,name,description,geometry_type,crs,format,authority_name,jurisdiction_code,confidence_score,verification_status,visibility,status) SELECT id,'EK-ADMIN','Ekiti Administrative Context','ekiti_admin_context','Ekiti Administrative Context','Administrative boundary context to be populated only from a licensed/verified boundary dataset.','Polygon','EPSG:4326','GeoJSON','Ekiti State Government','NG-EK',90,'Pending Source','Public','Active' FROM gis_data_sources WHERE name='Ekiti State Geospatial Data Center' AND NOT EXISTS (SELECT 1 FROM gis_layers WHERE layer_key='ekiti_admin_context');
INSERT INTO gis_layers (source_id,layer_code,layer_name,layer_key,name,description,geometry_type,crs,format,authority_name,jurisdiction_code,confidence_score,verification_status,visibility,status) SELECT id,'OSM-EK-INFRA','OSM Ekiti Infrastructure Context','osm_ekiti_infrastructure','OSM Ekiti Infrastructure Context','Non-cadastral roads, places and infrastructure context derived from OpenStreetMap.','Mixed','EPSG:4326','GeoJSON','OpenStreetMap contributors','NG-EK',85,'Pending Source','Public','Active' FROM gis_data_sources WHERE name='OpenStreetMap Nigeria' AND NOT EXISTS (SELECT 1 FROM gis_layers WHERE layer_key='osm_ekiti_infrastructure');
INSERT INTO gis_layer_publication_rules (layer_id,publication_status,allowed_fields,redaction_notes,status) SELECT id,'Restricted','Public metadata only','Authoritative land geometry remains restricted until source licence, authority and publication scope are verified.','Active' FROM gis_layers WHERE layer_key='ekiti_authoritative_land' AND NOT EXISTS (SELECT 1 FROM gis_layer_publication_rules WHERE layer_id=gis_layers.id);
INSERT INTO gis_layer_publication_rules (layer_id,publication_status,allowed_fields,redaction_notes,status) SELECT id,'Restricted','Layer metadata only','Administrative geometry requires a verified/licensed dataset before publication.','Active' FROM gis_layers WHERE layer_key='ekiti_admin_context' AND NOT EXISTS (SELECT 1 FROM gis_layer_publication_rules WHERE layer_id=gis_layers.id);
INSERT INTO gis_layer_publication_rules (layer_id,publication_status,allowed_fields,redaction_notes,status) SELECT id,'Restricted','Layer metadata only','OSM geometry publication requires attribution and licence validation before activation.','Active' FROM gis_layers WHERE layer_key='osm_ekiti_infrastructure' AND NOT EXISTS (SELECT 1 FROM gis_layer_publication_rules WHERE layer_id=gis_layers.id);